sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    /* ==========================================
       PAGE
       ========================================== */

    c.currentPage =
        'overview';


    /* ==========================================
       FORM
       ========================================== */

    c.showRecordForm =
        false;

    c.selectedRecord =
        null;

    c.savingRecord =
        false;

    c.formError =
        '';

    c.formSuccess =
        '';

    c.notesVisible =
        false;

    c.notesRequired =
        false;


    /* ==========================================
       FILTER OPTIONS
       ========================================== */

    c.useCaseOptions =
        c.data.filterOptions &&
        c.data.filterOptions.useCases
            ? c.data.filterOptions.useCases
            : [];

    c.priorityOptions =
        c.data.filterOptions &&
        c.data.filterOptions.priorities
            ? c.data.filterOptions.priorities
            : [];


    c.assignmentFilters = {

        use_case:
            '',

        current_priority:
            ''
    };


    c.filteredAssignmentIds =
        angular.copy(
            c.data.myAssignmentIds ||
            []
        );


    /* ==========================================
       CHANGE PAGE
       ========================================== */

    c.changePage =
        function(page) {

            c.currentPage =
                page;

            c.closeRecordForm();
        };


    /* ==========================================
       APPLY FILTERS
       ========================================== */

    c.applyAssignmentFilters =
        function() {

            var filtered = [];

            var ids =
                c.data.myAssignmentIds ||
                [];


            var selectedUseCase =
                String(
                    c.assignmentFilters.use_case ||
                    ''
                ).trim();


            var selectedPriority =
                String(
                    c.assignmentFilters.current_priority ||
                    ''
                ).trim();


            for (
                var i = 0;
                i < ids.length;
                i++
            ) {

                var sysId =
                    ids[i];


                var record =
                    c.data.records[
                        sysId
                    ];


                if (!record) {

                    continue;
                }


                /* --------------------------------
                   USE CASE
                   -------------------------------- */

                var useCaseMatch =
                    true;


                if (
                    selectedUseCase !== ''
                ) {

                    var recordUseCase =
                        String(
                            record.use_case ||
                            ''
                        ).trim();


                    var recordUseCaseDisplay =
                        String(
                            record.use_case_display ||
                            ''
                        ).trim();


                    useCaseMatch =
                        recordUseCase ===
                            selectedUseCase ||
                        recordUseCaseDisplay ===
                            selectedUseCase;
                }


                /* --------------------------------
                   PRIORITY
                   -------------------------------- */

                var priorityMatch =
                    true;


                if (
                    selectedPriority !== ''
                ) {

                    var recordPriority =
                        String(
                            record.current_priority ||
                            ''
                        ).trim();


                    var recordPriorityDisplay =
                        String(
                            record.current_priority_display ||
                            ''
                        ).trim();


                    priorityMatch =
                        recordPriority ===
                            selectedPriority ||
                        recordPriorityDisplay ===
                            selectedPriority;
                }


                if (
                    useCaseMatch &&
                    priorityMatch
                ) {

                    filtered.push(
                        sysId
                    );
                }
            }


            c.filteredAssignmentIds =
                filtered;
        };


    /* ==========================================
       CLEAR FILTERS
       ========================================== */

    c.clearAssignmentFilters =
        function() {

            c.assignmentFilters.use_case =
                '';

            c.assignmentFilters.current_priority =
                '';


            c.filteredAssignmentIds =
                angular.copy(
                    c.data.myAssignmentIds ||
                    []
                );
        };


    /* ==========================================
       OPEN RECORD
       ========================================== */

    c.openRecord =
        function(sysId) {

            c.formError =
                '';

            c.formSuccess =
                '';

            c.selectedRecord =
                null;


            var record =
                c.data.records[
                    sysId
                ];


            if (!record) {

                c.formError =
                    'The selected task could not be found.';

                return;
            }


            c.selectedRecord =
                angular.copy(
                    record
                );


            if (
                !c.selectedRecord.approval
            ) {

                c.selectedRecord.approval =
                    'requested';
            }


            c.selectedRecord.approval =
                String(
                    c.selectedRecord.approval
                ).toLowerCase();


            c.updateNotesVisibility();


            c.showRecordForm =
                true;
        };


    /* ==========================================
       ACCEPT TASK
       ========================================== */

    c.acceptRecord =
        function(sysId) {

            c.formError =
                '';

            c.formSuccess =
                '';


            var record =
                c.data.records[
                    sysId
                ];


            if (!record) {

                c.formError =
                    'The selected task could not be found.';

                return;
            }


            c.selectedRecord =
                angular.copy(
                    record
                );


            c.selectedRecord.approval =
                'approved';


            c.updateNotesVisibility();


            c.showRecordForm =
                true;
        };


    /* ==========================================
       CLOSE FORM
       ========================================== */

    c.closeRecordForm =
        function() {

            c.showRecordForm =
                false;

            c.selectedRecord =
                null;

            c.formError =
                '';

            c.formSuccess =
                '';

            c.savingRecord =
                false;

            c.notesVisible =
                false;

            c.notesRequired =
                false;
        };


    /* ==========================================
       NOTES VISIBILITY
       ========================================== */

    c.updateNotesVisibility =
        function() {

            if (!c.selectedRecord) {

                c.notesVisible =
                    false;

                c.notesRequired =
                    false;

                return;
            }


            var approval =
                String(
                    c.selectedRecord.approval ||
                    ''
                ).toLowerCase();


            if (
                approval === 'requested'
            ) {

                c.notesVisible =
                    false;

                c.notesRequired =
                    false;

            } else {

                /*
                 * Approved and Rejected
                 * both require Notes.
                 */

                c.notesVisible =
                    true;

                c.notesRequired =
                    true;
            }
        };


    /* ==========================================
       SAVE TASK
       ========================================== */

    c.saveRecord =
        function() {

            c.formError =
                '';

            c.formSuccess =
                '';


            if (
                !c.selectedRecord ||
                !c.selectedRecord.sys_id
            ) {

                c.formError =
                    'No task selected.';

                return;
            }


            var approval =
                String(
                    c.selectedRecord.approval ||
                    ''
                ).toLowerCase();


            var notes =
                String(
                    c.selectedRecord.notes ||
                    ''
                );


            if (
                approval !== 'requested' &&
                approval !== 'approved' &&
                approval !== 'rejected'
            ) {

                c.formError =
                    'Please select a valid approval status.';

                return;
            }


            if (
                (
                    approval === 'approved' ||
                    approval === 'rejected'
                ) &&
                notes.trim() === ''
            ) {

                c.formError =
                    'Notes are required when the approval is Approved or Rejected.';

                return;
            }


            c.savingRecord =
                true;


            c.server.get({

                action:
                    'saveRecord',

                sys_id:
                    c.selectedRecord.sys_id,

                approval:
                    approval,

                notes:
                    notes

            }).then(

                function(response) {

                    if (
                        response.data &&
                        response.data.saveError
                    ) {

                        c.formError =
                            response.data.saveError;

                        c.savingRecord =
                            false;

                        return;
                    }


                    if (
                        response.data
                    ) {

                        angular.extend(
                            c.data,
                            response.data
                        );
                    }


                    c.useCaseOptions =
                        c.data.filterOptions &&
                        c.data.filterOptions.useCases
                            ? c.data.filterOptions.useCases
                            : [];


                    c.priorityOptions =
                        c.data.filterOptions &&
                        c.data.filterOptions.priorities
                            ? c.data.filterOptions.priorities
                            : [];


                    c.filteredAssignmentIds =
                        angular.copy(
                            c.data.myAssignmentIds ||
                            []
                        );


                    c.applyAssignmentFilters();


                    if (
                        response.data &&
                        response.data.saveSuccess
                    ) {

                        c.formSuccess =
                            'Task updated successfully.';


                        setTimeout(
                            function() {

                                $scope.$apply(
                                    function() {

                                        c.closeRecordForm();

                                    }
                                );

                            },
                            700
                        );
                    }


                    c.savingRecord =
                        false;
                },


                function() {

                    c.formError =
                        'Unable to update the task. Please try again.';

                    c.savingRecord =
                        false;
                }
            );
        };


    /* ==========================================
       HORIZONTAL TABLE DRAG
       ========================================== */

    setTimeout(
        function() {

            var staffTable =
                document.getElementById(
                    'staffAssignmentScroll'
                );


            if (!staffTable) {

                return;
            }


            var dragging =
                false;

            var startX =
                0;

            var startScroll =
                0;


            staffTable.addEventListener(
                'mousedown',
                function(event) {

                    dragging =
                        true;

                    startX =
                        event.pageX -
                        staffTable.offsetLeft;

                    startScroll =
                        staffTable.scrollLeft;
                }
            );


            staffTable.addEventListener(
                'mouseleave',
                function() {

                    dragging =
                        false;
                }
            );


            staffTable.addEventListener(
                'mouseup',
                function() {

                    dragging =
                        false;
                }
            );


            staffTable.addEventListener(
                'mousemove',
                function(event) {

                    if (!dragging) {

                        return;
                    }


                    event.preventDefault();


                    var x =
                        event.pageX -
                        staffTable.offsetLeft;


                    var distance =
                        (
                            x -
                            startX
                        ) * 1.2;


                    staffTable.scrollLeft =
                        startScroll -
                        distance;
                }
            );

        },
        500
    );

};

sp_widget.css:
/* ==========================================
   STAFF DASHBOARD
   ========================================== */

.staff-dashboard {
    display: flex;
    min-height: 100vh;
    background: #f5f7f8;
    color: #243238;
    font-family: Arial, Helvetica, sans-serif;
}


/* ==========================================
   SIDEBAR
   ========================================== */

.staff-sidebar {
    width: 240px;
    min-width: 240px;
    background: #1E293B;
    border-right: 1px solid #334155;
    padding: 22px 16px;
    box-sizing: border-box;
}

.staff-brand {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 6px 8px 26px;
}

.staff-brand-icon {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #2563EB;
    color: #FFFFFF;
    font-size: 18px;
    font-weight: 700;
    border: 2px solid #60A5FA;
    box-shadow: 0 5px 12px rgba(37, 99, 235, 0.30);
}

.staff-brand-title {
    font-size: 16px;
    font-weight: 700;
    color: #FFFFFF;
}

.staff-brand-subtitle {
    margin-top: 3px;
    font-size: 12px;
    color: #94A3B8;
}

.staff-navigation {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.staff-nav-item {
    width: 100%;
    min-height: 44px;
    padding: 0 13px;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: #CBD5E1;
    display: flex;
    align-items: center;
    gap: 12px;
    text-align: left;
    cursor: pointer;
    font-size: 14px;
}

.staff-nav-item:hover {
    background: #334155;
    color: #FFFFFF;
}

.staff-nav-item.active {
    background: #2563EB;
    color: #FFFFFF;
    font-weight: 600;
}

.staff-nav-icon {
    width: 20px;
    text-align: center;
    font-size: 17px;
}


/* ==========================================
   CONTENT
   ========================================== */

.staff-content {
    flex: 1;
    min-width: 0;
    padding: 30px;
    overflow-x: hidden;
}

.staff-page {
    width: 100%;
}

.staff-page-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 24px;
}

.staff-page-header h1 {
    margin: 0;
    font-size: 27px;
    color: #123c3a;
}

.staff-page-header p {
    margin: 7px 0 0;
    color: #6d7977;
    font-size: 14px;
}


/* ==========================================
   KPI
   ========================================== */

.staff-kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.staff-kpi-card {
    background: #ffffff;
    border: 1px solid #dfe5e7;
    border-radius: 12px;
    padding: 21px;
}

.staff-kpi-label {
    font-size: 13px;
    color: #697674;
    font-weight: 600;
}

.staff-kpi-value {
    margin-top: 8px;
    font-size: 30px;
    font-weight: 700;
    color: #123c3a;
}

.staff-kpi-caption {
    margin-top: 5px;
    font-size: 12px;
    color: #8a9492;
}


/* ==========================================
   SECTION CARD
   ========================================== */

.staff-section-card {
    background: #ffffff;
    border: 1px solid #dfe5e7;
    border-radius: 12px;
    overflow: hidden;
    margin-bottom: 22px;
}

.staff-section-header {
    padding: 19px 21px;
    border-bottom: 1px solid #e5e9ea;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
}

.staff-section-header h2 {
    margin: 0;
    font-size: 18px;
    color: #123c3a;
}

.staff-section-header p {
    margin: 5px 0 0;
    color: #7a8583;
    font-size: 13px;
}

.staff-link-button {
    border: 0;
    background: transparent;
    color: #123c3a;
    font-weight: 600;
    cursor: pointer;
}

.staff-link-button:hover {
    text-decoration: underline;
}


/* ==========================================
   FILTERS
   ========================================== */

.staff-filter-card {
    background: #ffffff;
    border: 1px solid #dfe5e7;
    border-radius: 12px;
    margin-bottom: 22px;
    padding: 20px;
}

.staff-filter-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 18px;
}

.staff-filter-header h3 {
    margin: 0;
    color: #123c3a;
    font-size: 16px;
}

.staff-filter-header span {
    display: block;
    margin-top: 4px;
    color: #7a8583;
    font-size: 12px;
}

.staff-filter-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(200px, 1fr));
    gap: 16px;
}

.staff-filter-field label,
.staff-form-field label {
    display: block;
    margin-bottom: 7px;
    font-size: 12px;
    font-weight: 600;
    color: #4d5a58;
}

.staff-select {
    width: 100%;
    height: 40px;
    padding: 0 11px;
    border: 1px solid #ccd5d3;
    border-radius: 7px;
    background: #ffffff;
    color: #273533;
    box-sizing: border-box;
}

.staff-select:focus {
    outline: none;
    border-color: #123c3a;
}

.staff-clear-button {
    border: 1px solid #ccd5d3;
    border-radius: 7px;
    background: #ffffff;
    padding: 8px 13px;
    color: #53615f;
    cursor: pointer;
}

.staff-clear-button:hover {
    background: #f3f6f5;
}


/* ==========================================
   TABLE
   ========================================== */

.staff-table-scroll {
    width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    cursor: grab;
}

.staff-table-scroll:active {
    cursor: grabbing;
}

.staff-wide-table {
    max-height: 650px;
    overflow: auto;
}

.staff-task-table {
    width: max-content;
    min-width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

.staff-task-table th {
    position: sticky;
    top: 0;
    z-index: 2;
    background: #f1f5f4;
    color: #43514f;
    font-size: 11px;
    font-weight: 700;
    text-align: left;
    white-space: nowrap;
    padding: 12px 13px;
    border-bottom: 1px solid #d9e0de;
}

.staff-task-table td {
    padding: 12px 13px;
    border-bottom: 1px solid #e7ebeb;
    color: #465350;
    vertical-align: top;
    max-width: 260px;
    line-height: 1.45;
}

.staff-task-table tbody tr:hover {
    background: #fafcfc;
}

.staff-action-cell {
    min-width: 150px;
    white-space: nowrap;
}

.staff-empty-cell {
    text-align: center !important;
    padding: 35px !important;
    color: #8a9593 !important;
}


/* ==========================================
   BUTTONS
   ========================================== */

.staff-open-button,
.staff-accept-button {
    border: 0;
    border-radius: 6px;
    padding: 7px 11px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    margin-right: 5px;
}

.staff-open-button {
    background: #e8f0ed;
    color: #123c3a;
}

.staff-open-button:hover {
    background: #dce8e4;
}

.staff-accept-button {
    background: #123c3a;
    color: #ffffff;
}

.staff-accept-button:hover {
    opacity: 0.9;
}


/* ==========================================
   MODAL
   ========================================== */

.staff-modal-overlay {
    position: fixed;
    inset: 0;
    z-index: 1000;
    background: rgba(20, 31, 30, 0.55);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 25px;
    box-sizing: border-box;
}

.staff-modal {
    width: min(1050px, 100%);
    max-height: 92vh;
    background: #ffffff;
    border-radius: 14px;
    box-shadow: 0 18px 60px rgba(0, 0, 0, 0.18);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.staff-modal-header {
    padding: 20px 24px;
    border-bottom: 1px solid #e1e7e5;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}

.staff-modal-header h2 {
    margin: 0;
    color: #123c3a;
    font-size: 20px;
}

.staff-modal-header p {
    margin: 5px 0 0;
    color: #7a8583;
    font-size: 13px;
}

.staff-modal-close {
    width: 34px;
    height: 34px;
    border: 0;
    border-radius: 7px;
    background: #f2f5f4;
    color: #53615f;
    font-size: 22px;
    cursor: pointer;
}

.staff-modal-close:hover {
    background: #e8eeec;
}

.staff-modal-body {
    padding: 24px;
    overflow-y: auto;
}

.staff-form-section {
    margin-bottom: 25px;
}

.staff-form-section:last-child {
    margin-bottom: 0;
}

.staff-form-section-title {
    margin-bottom: 15px;
    padding-bottom: 9px;
    border-bottom: 1px solid #e5e9e8;
    color: #123c3a;
    font-size: 14px;
    font-weight: 700;
}

.staff-form-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
}

.staff-form-field {
    min-width: 0;
}

.staff-form-field input,
.staff-form-field textarea,
.staff-form-field select {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid #ccd5d3;
    border-radius: 7px;
    background: #ffffff;
    color: #283633;
    font-size: 13px;
    padding: 10px 11px;
}

.staff-form-field input {
    height: 40px;
}

.staff-form-field textarea {
    min-height: 95px;
    resize: vertical;
    line-height: 1.5;
}

.staff-form-field input[readonly],
.staff-form-field textarea[readonly] {
    background: #f5f7f7;
    color: #5d6967;
}

.staff-form-field select:focus,
.staff-form-field textarea:focus {
    outline: none;
    border-color: #123c3a;
}

.staff-full-field {
    grid-column: 1 / -1;
}

.staff-approval-select {
    background: #ffffff;
    font-weight: 600;
}

.staff-notes {
    min-height: 120px !important;
}

.staff-required {
    color: #b52b2b;
    font-size: 14px;
}

.staff-field-help {
    display: block;
    margin-top: 6px;
    color: #7b8785;
    font-size: 11px;
}


/* ==========================================
   MODAL FOOTER
   ========================================== */

.staff-modal-footer {
    padding: 16px 24px;
    border-top: 1px solid #e1e7e5;
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

.staff-cancel-button,
.staff-save-button {
    min-width: 110px;
    height: 40px;
    padding: 0 16px;
    border-radius: 7px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
}

.staff-cancel-button {
    border: 1px solid #ccd5d3;
    background: #ffffff;
    color: #53615f;
}

.staff-cancel-button:hover {
    background: #f4f6f5;
}

.staff-save-button {
    border: 0;
    background: #123c3a;
    color: #ffffff;
}

.staff-save-button:hover {
    opacity: 0.92;
}

.staff-save-button:disabled,
.staff-cancel-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}


/* ==========================================
   MESSAGES
   ========================================== */

.staff-form-message {
    margin: 16px 24px 0;
    padding: 11px 13px;
    border-radius: 7px;
    font-size: 13px;
}

.staff-error {
    background: #fff1f1;
    border: 1px solid #efcccc;
    color: #a22c2c;
}

.staff-success {
    background: #eef8f2;
    border: 1px solid #cce5d5;
    color: #2f6f45;
}


/* ==========================================
   RESPONSIVE
   ========================================== */

@media (max-width: 900px) {

    .staff-sidebar {
        width: 200px;
        min-width: 200px;
    }

    .staff-content {
        padding: 20px;
    }

    .staff-kpi-grid {
        grid-template-columns: 1fr;
    }
}


@media (max-width: 700px) {

    .staff-dashboard {
        flex-direction: column;
    }

    .staff-sidebar {
        width: 100%;
        min-width: 100%;
        border-right: 0;
        border-bottom: 1px solid #334155;
    }

    .staff-navigation {
        flex-direction: row;
        overflow-x: auto;
    }

    .staff-nav-item {
        min-width: max-content;
    }

    .staff-content {
        padding: 15px;
    }

    .staff-filter-grid,
    .staff-form-grid {
        grid-template-columns: 1fr;
    }

    .staff-full-field {
        grid-column: auto;
    }

    .staff-modal-overlay {
        padding: 10px;
    }

    .staff-modal {
        max-height: 96vh;
    }
}

sp_widget.script:
(function() {

    /* ==========================================
       DEFAULT DATA
       ========================================== */

    data.totalRequests = 0;
    data.pendingProblems = 0;
    data.resolvedRequests = 0;

    data.records = {};

    data.myAssignmentIds = [];
    data.recentAssignmentIds = [];
    data.historyIds = [];

    data.filterOptions = {
        useCases: [],
        priorities: []
    };

    data.saveSuccess = false;
    data.saveError = '';


    /* ==========================================
       STAFF GROUP / TASK TABLE
       ========================================== */

    var staffGroup =
        '4f04d11fdd1f03107f44143a6accf8c1';

    var taskTable =
        'x_snc_campus_foo_1_complain_tasks';


    /* ==========================================
       SAVE EXISTING TASK
       ========================================== */

    if (
        input &&
        input.action === 'saveRecord' &&
        input.sys_id
    ) {

        var updateTask =
            new GlideRecord(taskTable);

        if (!updateTask.get(input.sys_id)) {

            data.saveError =
                'The selected task could not be found.';

        } else if (
            updateTask.getValue('assignment_group') !==
            staffGroup
        ) {

            data.saveError =
                'You are not allowed to update this task.';

        } else {

            var newApproval =
                String(
                    input.approval || ''
                ).toLowerCase();

            var newNotes =
                String(
                    input.notes || ''
                );


            /* --------------------------------------
               VALID APPROVAL
               -------------------------------------- */

            if (
                newApproval !== 'requested' &&
                newApproval !== 'approved' &&
                newApproval !== 'rejected'
            ) {

                data.saveError =
                    'Please select a valid approval status.';

            }


            /* --------------------------------------
               NOTES REQUIRED FOR FINAL DECISION
               -------------------------------------- */

            else if (
                (
                    newApproval === 'approved' ||
                    newApproval === 'rejected'
                ) &&
                newNotes.trim() === ''
            ) {

                data.saveError =
                    'Notes are required when the approval is Approved or Rejected.';

            }


            /* --------------------------------------
               UPDATE EXISTING TASK
               -------------------------------------- */

            else {

                updateTask.setValue(
                    'approval',
                    newApproval
                );

                updateTask.setValue(
                    'notes',
                    newNotes
                );


                /* ----------------------------------
                   CLOSE TASK WHEN FINAL DECISION
                   ---------------------------------- */

                if (
                    newApproval === 'approved' ||
                    newApproval === 'rejected'
                ) {

                    updateTask.setValue(
                        'active',
                        false
                    );

                    updateTask.setValue(
                        'closed_at',
                        new GlideDateTime()
                    );

                    updateTask.setValue(
                        'closed_by',
                        gs.getUserID()
                    );
                }


                updateTask.update();

                data.saveSuccess =
                    true;
            }
        }
    }


    /* ==========================================
       KPI - TOTAL STAFF REQUESTS
       FROM COMPLAINT TASK TABLE
       ========================================== */

    var totalGA =
        new GlideAggregate(
            taskTable
        );

    totalGA.addQuery(
        'assignment_group',
        staffGroup
    );

    totalGA.addAggregate(
        'COUNT'
    );

    totalGA.query();

    if (totalGA.next()) {

        data.totalRequests =
            parseInt(
                totalGA.getAggregate(
                    'COUNT'
                ),
                10
            ) || 0;
    }


    /* ==========================================
       KPI - PENDING STAFF REQUESTS
       FROM COMPLAINT TASK TABLE
       ========================================== */

    var pendingGA =
        new GlideAggregate(
            taskTable
        );

    pendingGA.addQuery(
        'assignment_group',
        staffGroup
    );

    pendingGA.addQuery(
        'approval',
        'requested'
    );

    pendingGA.addAggregate(
        'COUNT'
    );

    pendingGA.query();

    if (pendingGA.next()) {

        data.pendingProblems =
            parseInt(
                pendingGA.getAggregate(
                    'COUNT'
                ),
                10
            ) || 0;
    }


    /* ==========================================
       KPI - RESOLVED REQUESTS
       TOTAL - PENDING
       ========================================== */

    data.resolvedRequests =
        data.totalRequests -
        data.pendingProblems;


    if (
        data.resolvedRequests < 0
    ) {

        data.resolvedRequests =
            0;
    }


    /* ==========================================
       USE CASE FILTER OPTIONS
       ========================================== */

    var useCaseChoice =
        new GlideRecord(
            'sys_choice'
        );

    useCaseChoice.addQuery(
        'name',
        taskTable
    );

    useCaseChoice.addQuery(
        'element',
        'use_case'
    );

    useCaseChoice.addQuery(
        'inactive',
        false
    );

    useCaseChoice.orderBy(
        'sequence'
    );

    useCaseChoice.query();

    while (
        useCaseChoice.next()
    ) {

        data.filterOptions.useCases.push({

            value:
                useCaseChoice.getValue(
                    'value'
                ),

            label:
                useCaseChoice.getValue(
                    'label'
                )
        });
    }


    /* ==========================================
       PRIORITY FILTER OPTIONS
       ========================================== */

    var priorityChoice =
        new GlideRecord(
            'sys_choice'
        );

    priorityChoice.addQuery(
        'name',
        taskTable
    );

    priorityChoice.addQuery(
        'element',
        'current_priority'
    );

    priorityChoice.addQuery(
        'inactive',
        false
    );

    priorityChoice.orderBy(
        'sequence'
    );

    priorityChoice.query();

    while (
        priorityChoice.next()
    ) {

        data.filterOptions.priorities.push({

            value:
                priorityChoice.getValue(
                    'value'
                ),

            label:
                priorityChoice.getValue(
                    'label'
                )
        });
    }


    /* ==========================================
       LOAD COMPLAINT TASK RECORDS
       ========================================== */

    var taskGR =
        new GlideRecord(
            taskTable
        );

    taskGR.orderByDesc(
        'sys_created_on'
    );

    taskGR.query();


    while (
        taskGR.next()
    ) {

        var sysId =
            taskGR.getUniqueValue();


        /* --------------------------------------
           FIELD HELPERS
           -------------------------------------- */

        function getValue(
            fieldName
        ) {

            if (
                taskGR.isValidField(
                    fieldName
                )
            ) {

                return taskGR.getValue(
                    fieldName
                ) || '';

            }

            return '';
        }


        function getDisplay(
            fieldName
        ) {

            if (
                taskGR.isValidField(
                    fieldName
                )
            ) {

                return taskGR.getDisplayValue(
                    fieldName
                ) || '';

            }

            return '';
        }


        /* --------------------------------------
           STORE TASK
           -------------------------------------- */

        data.records[sysId] = {

            sys_id:
                sysId,

            number:
                getValue(
                    'number'
                ),

            use_case:
                getValue(
                    'use_case'
                ),

            use_case_display:
                getDisplay(
                    'use_case'
                ),

            current_priority:
                getValue(
                    'current_priority'
                ),

            current_priority_display:
                getDisplay(
                    'current_priority'
                ),

            student_count:
                parseInt(
                    getValue(
                        'student_count'
                    ),
                    10
                ) || 0,

            state:
                getValue(
                    'state'
                ),

            state_display:
                getDisplay(
                    'state'
                ),

            assignment_group:
                getValue(
                    'assignment_group'
                ),

            assignment_group_display:
                getDisplay(
                    'assignment_group'
                ),

            problem_type:
                getValue(
                    'problem_type'
                ),

            problem_type_display:
                getDisplay(
                    'problem_type'
                ),

            short_description:
                getValue(
                    'short_description'
                ),

            approval:
                getValue(
                    'approval'
                ),

            approval_display:
                getDisplay(
                    'approval'
                ),

            use_case_number:
                getValue(
                    'use_case_number'
                ),

            mess_hall:
                getValue(
                    'mess_hall'
                ),

            mess_hall_display:
                getDisplay(
                    'mess_hall'
                ),

            meal_type:
                getValue(
                    'meal_type'
                ),

            meal_type_display:
                getDisplay(
                    'meal_type'
                ),

            priority_reason:
                getValue(
                    'priority_reason'
                ),

            recomended_actions:
                getValue(
                    'recomended_actions'
                ),

            resolution_status:
                getValue(
                    'resolution_status'
                ),

            resolution_status_display:
                getDisplay(
                    'resolution_status'
                ),

            notes:
                getValue(
                    'notes'
                ),

            updated:
                getValue(
                    'sys_updated_on'
                ),

            updated_display:
                getDisplay(
                    'sys_updated_on'
                )
        };


        /* ======================================
           STAFF ASSIGNED TASKS
           ====================================== */

        if (
            getValue(
                'assignment_group'
            ) === staffGroup &&
            getValue(
                'approval'
            ) === 'requested'
        ) {

            data.myAssignmentIds.push(
                sysId
            );
        }


        /* ======================================
           STAFF TASK HISTORY
           ====================================== */

        if (
            getValue(
                'assignment_group'
            ) === staffGroup &&
            (
                getValue(
                    'approval'
                ) === 'approved' ||
                getValue(
                    'approval'
                ) === 'rejected'
            )
        ) {

            data.historyIds.push(
                sysId
            );
        }
    }


    /* ==========================================
       RECENT STAFF TASKS
       ========================================== */

    for (
        var recentIndex = 0;
        recentIndex <
            data.myAssignmentIds.length &&
        recentIndex < 5;
        recentIndex++
    ) {

        data.recentAssignmentIds.push(
            data.myAssignmentIds[
                recentIndex
            ]
        );
    }

})();
